	public override void OnEnter()
	{
		base.OnEnter();
		if (isUltimate)
		{
			ultStarted = false;
			firstAnim = true;
			targetVector = inputVector;
			perpendVec = Globals.GetPerpendicular(targetVector) * 0.42f;
		}
	}

	public override void ExecuteSkill()
	{
		if (isUltimate)
		{
			if (!ultStarted)
			{
				ultStarted = true;
				ultStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.0625f, 15);
			}
			switch (ChaosStopwatch.CheckInterval(ultStopwatchID))
			{
			case StopwatchState.Ready:
				SetUltInput();
				if (firstAnim)
				{
					firstAnim = false;
				}
				else
				{
					parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animExecTime);
				}
				spawnPosition = (Vector2)parent.attackOriginTrans.position + targetVector * 0.5f + Vector2.Lerp(-perpendVec, perpendVec, UnityEngine.Random.value);
				CreateEarthCascade(spawnPosition, targetVector);
				SoundManager.PlayAudioWithDistance("StandardThrow", spawnPosition);
				break;
			case StopwatchState.Done:
				base.ExecuteSkill();
				break;
			}
			if (!CancelToDash())
			{
			}
		}
		else
		{
			base.ExecuteSkill();
			perpendVec = Globals.GetPerpendicular(inputVector, !parent.isFacingRight) * 0.25f;
			spawnPosition = (Vector2)parent.attackOriginTrans.position + inputVector - perpendVec * projectileCount * 0.5f;
			for (int i = 0; i < projectileCount; i++)
			{
				CreateEarthCascade(spawnPosition + i * perpendVec + (projectileCount - i) * inputVector * 0.125f, inputVector, (float)i * 0.05f);
			}
			SoundManager.PlayAudioWithDistance("StandardThrow", spawnPosition);
		}
	}

	private void SetUltInput()
	{
		inputVector = GetInputVector(faceInputVector: false, useAimVector: true, ignoreZero: false);
		if (inputVector != Vector2.zero)
		{
			targetVector = (targetVector + inputVector * 0.125f).normalized;
			parent.FaceTarget(targetVector + (Vector2)parent.transform.position);
			perpendVec = Globals.GetPerpendicular(targetVector) * 0.75f;
		}
	}

	private void CreateEarthCascade(Vector2 givenPosition, Vector2 givenVector, float givenDelay = 0f)
	{
		currentEC = (EarthCascade)CreateProjectile(EarthCascade.Prefab, givenPosition);
		FireProjectile(currentEC, givenVector, setKnockbackVector: true, 0f, 0f, string.Empty);
		currentEC.SetReleaseVars(givenVector, givenDelay);
		if (isUltimate)
		{
			currentEC.disableOnHit = false;
		}
	}
}

