		releaseMoveSpeed = moveSpeed;
	}

	public override void Start()
	{
		base.Start();
		moveSpeed = 0f;
		if (releaseDelay > 0f)
		{
			releaseStopwatchID = ChaosStopwatch.Begin(releaseDelay);
		}
	}

	public override void Update()
	{
		if (!released)
		{
			if (!ChaosStopwatch.Check(releaseStopwatchID))
			{
				return;
			}
			released = true;
			RockBurstDirectionalEffect poolItem = PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect");
			RockDebrisType debrisType = RockDebrisType.Dark;
			int? particleCount = 1;
			Vector3? position = transform.position;
			Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
			poolItem.EmitSingle(debrisType, particleCount, position, null, localEulerAngles);
			ReleaseProjectile();
		}
		base.Update();
	}

	public override void ResetProjectile()
	{
		base.ResetProjectile();
		PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect").EmitSingle(RockDebrisType.Dark, 1, transform.position);
	}

	public void SetReleaseVars(Vector2 givenVector, float givenDelay = 0f)
	{
		moveVector = givenVector;
		if (givenDelay > 0f)
		{
			releaseDelay = givenDelay;
		}
	}

	private void ReleaseProjectile()
	{
		InitTimers();
		moveSpeed = releaseMoveSpeed;
		EnableColliders();
		SoundManager.PlayAudioWithDistance("EarthDust", transform.position);
	}

	private void EnableColliders(bool status = true)
	{
		Collider2D[] array = colliders;
		foreach (Collider2D collider2D in array)
		{
			collider2D.enabled = status;
		}
	}
}
