			vineEffects[waveCount].Emit(3, activationPosition, ParticleEffectOverrides.StartLifeTime0p5);
			PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(2, activationPosition, RockDebrisEmitter.FloorExplosionOverrideShort);
			attackCollider.size = new Vector2(1.5f, spacing * (float)wavesElapsed + 0.5f);
