			if (!skipCameraShake)
			{
				CameraController.ShakeCamera(0.25f);
			}
		}
	}

	public void FlipAttackCollider()
	{
		attackCollider.enabled = false;
		attackCollider.enabled = true;
	}

	private void OnDestroy()
	{
		if (churningAudio != null && churningAudio.isPlaying)
		{
			churningAudio.Stop();
		}
		if (vineEffects == null)
		{
			return;
		}
		for (int i = 0; i < vineEffects.Length; i++)
		{
			if (vineEffects[i] != null)
			{
				vineEffects[i].Stop();
			}
		}
	}
}

