public class BasicMinion : Entity
{
	public class MinionIdleState(string newName, FSM newFSM, BasicMinion newEnt) : State<BasicMinion>(newName, newFSM, newEnt)
	{
		public string animName = string.Empty;
		public Vector2 parentPosition;
		public override void OnEnter()
		{
			parent.isIdle = true;
			if (animName != string.Empty)
			{
				parent.anim.PlayDirectional(animName);
			}
		}
		public override void Update()
		{
			if (!(parent.parentTrans == null))
			{
				parentPosition = parent.parentTrans.position;
				if (Vector2.Distance(parent.transform.position, parentPosition) > parent.idleDistToParent)
				{
					OnFollow();
				}
				else if (parent.UpdateTargetInfo() != null && parent.CanApproachTarget(parentPosition, parent.closestTargetInfo.position, parent.maxDistToParent + parent.attackRadius))
				{
					OnChase();
				}
			}
		}
		public virtual void OnFollow()
		{
			fsm.ChangeState("FollowParent");
		}
		public virtual void OnChase()
		{
			parent.isIdle = false;
			fsm.ChangeState("MoveToEnemy");
		}
	}
	public class FollowParentState(string newName, FSM newFSM, BasicMinion newEnt) : State<BasicMinion>(newName, newFSM, newEnt)
	{
		public string animName = string.Empty;
		public Vector2 parentPosition;
		public Vector2 endPosition;
		public float endRange;
		public override void OnEnter()
		{
			if (animName != string.Empty)
			{
				parent.anim.PlayDirectional(animName);
			}
			parent.PlayMoveAudio();
		}
		public override void Update()
		{
			if (parent.parentTrans == null)
			{
				fsm.ChangeState(fsm.defaultStateName);
				return;
			}
			parentPosition = parent.parentTrans.position;
			endPosition = Globals.GetLinecastVector(parentPosition, parentPosition + parent.followOffset, parent.lineOfSightLayerMask);
			endRange = ((!parent.isIdle) ? (parent.maxDistToParent * 0.75f) : (parent.idleDistToParent * 0.75f));
			if (!parent.HandleTeleportToPlayer(parentPosition) && parent.MoveToTargetOrFollowPath(parent.transform.position, endPosition, parent.teleportToPlayerRange, endRange, animName))
			{
				parent.movement.MoveToTarget(parentPosition, 0f, 0f, dryRun: false, endMovementOnFinish: false);
				fsm.ChangeState(fsm.defaultStateName);
			}
		}
	}
	public class MoveToEnemyState(string newName, FSM newFSM, BasicMinion newEnt) : State<BasicMinion>(newName, newFSM, newEnt)
	{
		public string animName = string.Empty;
		public Vector2 currentPosition;
		public Vector2 parentPosition;
		public Vector2 targetPosition;
		public bool transitionToAttack;
		public bool moveOnTransition = true;
		public override void OnEnter()
		{
			if (animName != string.Empty)
			{
				parent.anim.PlayDirectional(animName);
			}
			parent.PlayMoveAudio();
		}
		public override void Update()
		{
			if (parent.parentTrans == null)
			{
				fsm.ChangeState(fsm.defaultStateName);
				return;
			}
			currentPosition = parent.transform.position;
			parentPosition = parent.parentTrans.position;
			if (Vector2.Distance(currentPosition, parentPosition) > parent.maxDistToParent + parent.attackRadius || parent.UpdateTargetInfo() == null)
			{
				fsm.ChangeState("FollowParent");
				return;
			}
			targetPosition = parent.closestTargetInfo.position;
			if (parent.MoveToTargetOrFollowPath(currentPosition, targetPosition, parent.maxDistToParent + parent.attackRadius, parent.attackRadius * 0.9f, animName))
			{
				transitionToAttack = Entity.HasLineOfSight(currentPosition, targetPosition, parent.attackRadius, parent.lineOfSightLayerMask);
				fsm.ChangeState((!transitionToAttack) ? "FollowParent" : "Attack");
				if (moveOnTransition && (!transitionToAttack || Vector2.Distance(currentPosition, targetPosition) > parent.attackRadius * 0.9f))
				{
					parent.movement.MoveToTarget(targetPosition, 0f, 0f, dryRun: false, endMovementOnFinish: false);
				}
			}
		}
	}
	public class MinionAttackState(string newName, FSM newFSM, BasicMinion newEnt) : State<BasicMinion>(newName, newFSM, newEnt)
	{
		public string animName = "Attack";
		public bool useDirectionalAnim = true;
		public float atkAnimExecTime = 0.25f;
		public bool attackCompleted;
		public string attackAudioID = "StandardHeavySwing";
		public bool playAudio = true;
		public bool audioPlayed;
		public float currentAnimTime;
		private bool firstFrame;
