			parent.FaceTarget(parent.closestTargetInfo.hurtBoxTransform.position);
			parent.anim.PlayDirectional((!useDirectionalAnim) ? animName : (animName + parent.facingDirection));
			audioPlayed = !playAudio;
			firstFrame = true;
