public class ElementalWeaknessDotEffect : DoTEffect
{
	private GameObject effectPrefab;
	private BaseEffect effectObject;
	private ElementType element;
	private NumVarStatMod elementMod;
	private Health parentHealth;
	public ElementalWeaknessDotEffect(Entity givenEntity, ElementType givenElement, float givenMultiplier, float givenDuration)
		: base(string.Empty, string.Empty, 0, givenEntity, null)
	{
		if (!(givenEntity == null))
		{
			ID = givenElement.ToString() + "WeakDotMod";
			useInterval = false;
			damageInterval = givenDuration;
			damageStopwatchID = ChaosStopwatch.Begin(damageInterval);
			parentHealth = givenEntity.health;
			element = givenElement;
			elementMod = new NumVarStatMod(ID, givenMultiplier, 10, VarStatModType.Multiplicative);
		}
	}
	public override bool Update()
	{
		if (parentEntity == null || parentHealth == null || parentHealth.healthStat.CurrentValue <= 0f || ChaosStopwatch.Check(damageStopwatchID))
		{
			CleanUp();
			ToggleMods(status: false);
			if (effectObject != null)
			{
				effectObject.Disable();
			}
			return true;
		}
		return false;
	}
	public override void Init()
	{
		if (!(parentEntity == null))
		{
			if (effectObject == null && effectPrefab != null)
			{
				CreateEffectObject();
			}
			ToggleMods(status: true);
		}
	}
	private void ToggleMods(bool status)
	{
		if (!(parentEntity == null) && !(parentHealth == null) && parentHealth.elemModDict.ContainsKey(element))
		{
			parentHealth.elemModDict[element].Modify(elementMod, status);
		}
	}
	private void CreateEffectObject()
	{
		effectObject = Globals.ChaosInst<BaseEffect>(effectPrefab, parentEntity.transform.parent, parentEntity.hurtBoxTransform.position);
		effectObject.entity = parentEntity;
	}
}

public class UseHammerThrow : ProjectileAttackState
{
	public new static string staticID = "UseHammerThrow";

	private EarthHammer currentEH;

	private ChaosQuickStopwatch spinStopwatch = new ChaosQuickStopwatch();

	private float spinLerpVal;

	private bool spinStarted;

	private bool spinCompleted;

	private Vector2 throwVector;

	private Vector3 startRoteVec;

	private Vector3 endRoteVec;

	private Vector3 currentRoteVec;

	private int calcRoteIndex;

	private float[] roteCountArr = new float[3] { 2.5f, 3.5f, 5.5f };

	private float[] rotePerSecArr = new float[3] { 4f, 5f, 6f };

	private float calcRoteCount;

	private float calcRotePerSec;

	private float currentRoteVal;

	private float hammerScale = 1f;

	private bool targetCompleted;

	private bool initialSwing;

	private ChaosQuickStopwatch cancelStopwatch = new ChaosQuickStopwatch(0.5f);

	public override string OnEnterAnimStr => (!parent.isFacingRight) ? parent.BackhandAnimStr : parent.ForehandAnimStr;

	public UseHammerThrow(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		isMovementSkill = true;
		isMeleeSkill = true;
		isProjectileSkill = true;
		disableStartCooldown = true;
		SetAnimTimes(0f, 0.2f, 0.3f, 0.5f, 0.6f);
	}

	public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
	{
		base.SetEmpowered(givenStatus, givenMod);
		hammerScale = ((!IsEmpowered) ? 1f : 1.25f);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		parent.movement.moveVector = inputVector;
		parent.movement.MoveToMoveVector();
		calcRoteIndex = (isUltimate ? 2 : (IsEmpowered ? 1 : 0));
		calcRoteCount = roteCountArr[calcRoteIndex];
		calcRotePerSec = rotePerSecArr[calcRoteIndex];
		spinStopwatch.SetDelay(calcRoteCount / calcRotePerSec);
		spinStarted = false;
		spinCompleted = false;
		targetCompleted = false;
		initialSwing = true;
	}

	public override void ExecuteSkill()
	{
		if (!spinStarted)
		{
			spinStarted = true;
			spinStopwatch.IsRunning = true;
			parent.FaceTarget(parent.transform.position + Vector3.right);
			parent.anim.Play("SpinReverse", -1, animExecTime);
			if (currentEH == null)
			{
				CreateHammer();
			}
			cancelStopwatch.IsRunning = true;
		}
		if (spinCompleted || currentEH == null || (!cancelStopwatch.IsRunning && CancelToDash(enableButtonHeld: true)))
		{
			base.ExecuteSkill();
			StartCooldownTimer();
		}
	}

	public override void FixedUpdate()
	{
		if (!spinStarted || spinCompleted || currentEH == null)
		{
			return;
		}
		spinLerpVal = spinStopwatch.TimePercentage;
		currentRoteVec = Vector3.Lerp(startRoteVec, endRoteVec, spinLerpVal);
		currentEH.transform.localEulerAngles = currentRoteVec;
		currentEH.transform.position = parent.attackOriginTrans.position;
		if (currentRoteVal < currentRoteVec.z)
		{
			currentRoteVal += 360f;
			currentEH.ToggleAttack(givenStatus: false);
			currentEH.ToggleAttack(givenStatus: true);
			if (initialSwing)
			{
				initialSwing = false;
			}
			else
			{
				SoundManager.PlayAudioWithDistance("StandardHeavySwing", parent.transform.position, null, 24f, -1f, 1f, ignoreTimeRestriction: true);
			}
		}
		if (spinLerpVal < 1f)
		{
			if (!targetCompleted)
			{
				inputVector = GetInputVector();
				parent.movement.moveVector = inputVector;
			}
			parent.movement.MoveToMoveVector(3f);
			if (!currentEH.trailEnabled && spinLerpVal > 0.2f)
			{
				currentEH.ToggleTrail();
			}
		}
		else if (!targetCompleted)
		{
			targetCompleted = true;
			throwVector = inputVector;
			endRoteVec = Globals.GetRotationVector(throwVector);
			startRoteVec.z = Globals.TrueMod(currentEH.transform.localEulerAngles.z, 360f);
			endRoteVec.z = Globals.TrueMod(endRoteVec.z, 360f);
			if (startRoteVec.z > endRoteVec.z)
			{
				endRoteVec.z += 360f;
			}
			spinStopwatch.SetDelay((endRoteVec.z - startRoteVec.z) / (360f * calcRotePerSec), stopCurrent: false, autoStart: true);
		}
		else
		{
			currentEH.ToggleTrail(enableTrail: false);
			spinCompleted = true;
			parent.FaceTarget((Vector2)parent.transform.position + throwVector);
			parent.anim.PlayDirectional(parent.BackhandAnimStr, -1, animExecTime);
			parent.movement.moveVector = -throwVector;
			parent.movement.MoveToMoveVector(20f);
			ThrowHammer();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		if (!spinCompleted && currentEH != null)
		{
			currentEH.ResetProjectile();
		}
		currentEH = null;
		if (!skillExecuted)
		{
			StartCooldownTimer();
		}
	}

	private void CreateHammer()
	{
		SetSkillLevel((!isUltimate) ? 1 : 2);
		currentEH = (EarthHammer)CreateProjectile(EarthHammer.Prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(-inputVector));
		throwVector = inputVector;
		currentEH.transform.localScale *= hammerScale;
		startRoteVec = currentEH.transform.localEulerAngles;
		endRoteVec = startRoteVec;
		endRoteVec.z += 360f * calcRoteCount;
		currentRoteVal = startRoteVec.z;
	}

	private void ThrowHammer()
	{
		SetSkillLevel(3);
		if (!(currentEH == null))
		{
			currentEH.transform.localEulerAngles = Globals.GetRotationVector(throwVector);
			currentEH.goThroughWalls = false;
			currentEH.InitThrow((!isUltimate) ? 4 : 5);
			FireProjectile(currentEH, throwVector, setKnockbackVector: true, 0f, 0f, string.Empty, setAtkInfo: true);
		}
	}
}

