	public class UseWhirlingAxe : SkillState
	{
		public new static string staticID = "UseWhirlingAxe";

		private WhirlingAxe primaryWA;

		private WhirlingAxe currentWA;

		private WhirlingAxe createdWA;

		private List<WhirlingAxe> axeList = new List<WhirlingAxe>();

		private int atkMaxCount;

		private int atkCounter;

		private bool atkCompleted;

		private bool queueListClear;

		public override string OnEnterAnimStr => parent.ForehandAnimStr;

		public UseWhirlingAxe(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			isProjectileSkill = true;
			disableStartCooldown = true;
			SetAnimTimes(0.15f, 0.2f, 0.3f, 0.55f, 0.75f);
		}

		public override bool IsReady()
		{
			return (!(primaryWA != null)) ? base.IsReady() : primaryWA.isReady;
		}

		public override void OnEnter()
		{
			base.OnEnter();
			CameraController.ShakeCamera(0.2f);
			if (isUltimate)
			{
				ClearList();
				if (primaryWA != null)
				{
					primaryWA.Reset();
					primaryWA = null;
				}
			}
			if (primaryWA == null)
			{
				primaryWA = CreateWhirlingAxe();
			}
			primaryWA.ThrowAxe(inputVector);
			createdWA = null;
			axeList.RemoveNullValues();
			atkMaxCount = (isUltimate ? 6 : ((axeList.Count <= 1) ? 1 : axeList.Count));
			atkCounter = 0;
			atkCompleted = !IsEmpowered;
			queueListClear = false;
		}

		public override void ExecuteSkill()
		{
			if (CancelToDash(enableButtonHeld: true))
			{
				return;
			}
			if (!atkCompleted)
			{
				parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animStartTime);
				if (axeList.Count > atkCounter)
				{
					currentWA = axeList[atkCounter];
				}
				if (currentWA == null)
				{
					currentWA = CreateWhirlingAxe(isSecondary: true, atkCounter);
					axeList.Add(currentWA);
				}
				currentWA.ThrowAxe(inputVector + UnityEngine.Random.insideUnitCircle * 0.08f);
				currentWA = null;
				atkCounter++;
				atkCompleted = atkCounter >= atkMaxCount;
			}
			else
			{
				base.ExecuteSkill();
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			if (queueListClear)
			{
				ClearList();
			}
		}

		private WhirlingAxe CreateWhirlingAxe(bool isSecondary = false, int givenIndex = 0)
		{
			createdWA = ChaosInst<WhirlingAxe>(WhirlingAxe.Prefab);
			createdWA.attack.SetAttackInfo(parent.skillCategory, skillID, 1, isUltimate);
			createdWA.followTrans = parent.transform;
			createdWA.isEmpowered = IsEmpowered;
			createdWA.isUltimate = isUltimate;
			if (isSecondary)
			{
				createdWA.InitFollowup(givenIndex + 1, atkMaxCount + 2);
			}
			else
			{
				WhirlingAxe whirlingAxe = createdWA;
				whirlingAxe.onDeadEventHandlers = (WhirlingAxe.OnDeadEventHandler)Delegate.Remove(whirlingAxe.onDeadEventHandlers, new WhirlingAxe.OnDeadEventHandler(OnAxeDead));
				WhirlingAxe whirlingAxe2 = createdWA;
				whirlingAxe2.onDeadEventHandlers = (WhirlingAxe.OnDeadEventHandler)Delegate.Combine(whirlingAxe2.onDeadEventHandlers, new WhirlingAxe.OnDeadEventHandler(OnAxeDead));
			}
			return createdWA;
		}

		private void OnAxeDead(WhirlingAxe givenAxe)
		{
			if (givenAxe != null)
			{
				givenAxe.onDeadEventHandlers = (WhirlingAxe.OnDeadEventHandler)Delegate.Remove(givenAxe.onDeadEventHandlers, new WhirlingAxe.OnDeadEventHandler(OnAxeDead));
			}
			if (!isUltimate)
			{
				if (parent.currentStateName != skillID)
				{
					ClearList();
				}
				else
				{
					queueListClear = true;
				}
				StartCooldownTimer();
			}
		}

		private void ClearList()
		{
			queueListClear = false;
			foreach (WhirlingAxe axe in axeList)
			{
				if (axe != null)
				{
					axe.Reset();
				}
			}
			axeList.Clear();
		}
	}

