		{
			if (parent.followTrans == null || ChaosStopwatch.Check(parent.lifeStopwatchID))
			{
				fsm.ChangeState("Dead");
				return;
			}
			if (isOrbiting)
			{
				parent.movement.OrbitTarget(parent.followTrans.position);
				return;
			}
			followVector = parent.followTrans.position - parent.transform.position;
			sqDistToParent = followVector.sqrMagnitude;
			if (sqDistToParent < 1f)
			{
				parent.isReady = true;
				isOrbiting = true;
				parent.movement.InitOrbitAngle(Globals.GetRotatedCircleVector(parent.maxIndex, parent.atkIndex, followVector.normalized));
			}
			else
			{
				parent.movement.moveVector = followVector.normalized;
				parent.movement.MoveToMoveVector();
			}
		}
	}
	public class AttackState : State<WhirlingAxe>
	{
		private Vector3 reposOffset;
		private float swLerpValue;
		private ChaosQuickStopwatch reposStopwatch = new ChaosQuickStopwatch(0.08f);
		private bool reposCompleted;
		private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.25f);
		private bool atkCompleted;
		private ChaosQuickStopwatch delayStopwatch = new ChaosQuickStopwatch(0.25f);
		private bool delayCompleted;
		private ChaosQuickStopwatch retStopwatch = new ChaosQuickStopwatch(0.5f);
		private bool retCompleted;
		private float retSpeed = 20f;
		private bool isThrownRight;
		private float readyRoteVal = 45f;
		private float throwRoteVal = 120f;
		private float extraRoteVal = 720f;
		private Vector3 baseRotation = Vector3.zero;
		private Vector3 readyRotation = new Vector3(0f, 0f, 45f);
		private Vector3 throwRotation = new Vector3(0f, 0f, 120f);
		private Vector2 basePosition = Vector2.up;
		private Vector2 readyPosition = new Vector2(0f, 1.25f);
		private Vector2 throwPosition = new Vector2(0f, 0.625f);
		private Vector2 retVector;
		public AttackState(string newName, FSM newFSM, WhirlingAxe newEnt)
			: base(newName, newFSM, newEnt)
		{
			retSpeed = parent.movement.moveSpeedStat.CurrentValue;
			if (parent.isFollowup)
			{
				reposStopwatch.SetDelay(0.05f);
			}
		}
		public override void OnEnter()
		{
			reposStopwatch.IsRunning = true;
			reposOffset = -parent.atkVector;
			reposCompleted = false;
			atkCompleted = false;
			delayCompleted = false;
			retCompleted = false;
			if (parent.atkVector.x > 0f)
			{
				isThrownRight = true;
				readyRotation.z = readyRoteVal;
				throwRotation.z = 0f - (throwRoteVal + extraRoteVal);
			}
			else
			{
				isThrownRight = false;
				readyRotation.z = 0f - readyRoteVal;
				throwRotation.z = throwRoteVal + extraRoteVal;
			}
			parent.isReady = false;
			parent.anim.Play((!parent.isFollowup) ? "Attack" : "AttackAlt", -1, 0f);
		}
		public override void FixedUpdate()
		{
			if (!reposCompleted)
			{
				swLerpValue = reposStopwatch.TimePercentage;
				if (parent.followTrans != null)
				{
					parent.transform.position = Vector2.Lerp(parent.transform.position, parent.followTrans.position + reposOffset, swLerpValue);
				}
				HandleSpriteVisuals(swLerpValue, 0);
				if (swLerpValue >= 1f)
				{
					reposCompleted = true;
					atkStopwatch.IsRunning = true;
					parent.attack.atkInfo = ((!parent.isEmpowered) ? parent.throwInfo : parent.empInfo);
					SoundManager.PlayWithDistAndSPR("AxeWhirl", parent.transform.position);
				}
			}
			else if (!atkCompleted)
			{
				swLerpValue = atkStopwatch.TimePercentage;
				parent.rigidbody2D.velocity = parent.atkVector * parent.atkSpeed;
				HandleSpriteVisuals(swLerpValue, 1);
				if (swLerpValue >= 1f)
				{
					atkCompleted = true;
					delayStopwatch.IsRunning = true;
					throwRotation.z += ((!isThrownRight) ? (0f - throwRoteVal) : throwRoteVal);
					OnLanding();
				}
			}
			else if (!delayCompleted)
			{
				delayCompleted = !delayStopwatch.IsRunning;
				if (delayCompleted)
				{
					retStopwatch.IsRunning = true;
					parent.attack.atkInfo = parent.returnInfo;
					parent.attackCollider.enabled = true;
					SoundManager.PlayAudioWithDistance("AxeWhirl", parent.transform.position, null, 24f, 0.125f);
				}
			}
			else if (!retCompleted)
			{
				swLerpValue = retStopwatch.TimePercentage;
				if (parent.followTrans != null)
				{
					retVector = parent.followTrans.position - parent.transform.position;
				}
				if (retVector.sqrMagnitude < 2f)
				{
					swLerpValue = 1f;
				}
				else
				{
					retVector.Normalize();
					parent.rigidbody2D.velocity = retVector * retSpeed;
					parent.attack.knockbackOverwriteVector = retVector;
				}
				HandleSpriteVisuals(swLerpValue, 2);
				if (swLerpValue >= 1f)
				{
					retCompleted = true;
				}
			}
			else
			{
				fsm.ChangeState(fsm.defaultStateName);
			}
		}
		public override void OnExit()
		{
			parent.attack.atkInfo = parent.returnInfo;
			parent.attackCollider.enabled = true;
		}
		private void HandleSpriteVisuals(float givenValue, int givenState)
		{
			switch (givenState)
			{
			case 0:
				parent.spriteTrans.localPosition = Vector3.Lerp(basePosition, readyPosition, givenValue);
				parent.spriteTrans.localEulerAngles = Vector3.Lerp(baseRotation, readyRotation, givenValue);
				break;
			case 1:
				parent.spriteTrans.localPosition = Vector3.Lerp(readyPosition, throwPosition, givenValue * givenValue);
				parent.spriteTrans.localEulerAngles = Vector3.Lerp(readyRotation, throwRotation, givenValue);
				break;
			default:
				parent.spriteTrans.localPosition = Vector3.Lerp(parent.spriteTrans.localPosition, basePosition, givenValue);
				parent.spriteTrans.localEulerAngles = Vector3.Lerp(throwRotation, baseRotation, givenValue);
				break;
			}
		}
		private void OnLanding()
		{
			parent.attackCollider.enabled = false;
			parent.movement.EndMovement();
			PoolManager.GetPoolItem<ParticleEffect>("FloorCraterSmall").Emit(1, parent.transform.position);
		}
	}
