using UnityEngine;
public class PlantBarrage : MonoBehaviour
{
	private static GameObject prefab;
	public Animator cactusAnim;
	public Movement movement;
	public Attack attack;
	public CircleCollider2D attackCollider;
	public ParticleSystem thornPartSys;
	public int hitCount = 10;
	public float hitDelay = 0.25f;
	private int hitCDStopwatchID;
	private bool destroyQueued;
	private bool isEmpowered;
	private Vector2 startPosition;
	private Vector2 endPosition;
	private int moveStopwatchID;
	private float moveTime;
	private float moveLerpValue;
	private bool moveCompleted;
	private Transform orbitTrans;
	private bool useOrbit;
	private int pongCount = 3;
	private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(0.2f);
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/PlantBarrage.prefab"));
	public void Initialize(bool givenEmp, Vector2 givenStart, Vector2 givenEnd, int givenPong, int givenCount, float givenDelay)
	{
		isEmpowered = givenEmp;
		startPosition = givenStart;
		endPosition = Globals.GetLinecastVector(givenStart, givenEnd, ChaosCollisions.layerAll);
		pongCount = givenPong;
		hitCount = givenCount;
		hitDelay = givenDelay;
		moveTime = (float)givenCount * hitDelay;
	}
	public void InitOrbit(Transform givenTrans, Vector2 givenVector)
	{
		useOrbit = true;
		orbitTrans = givenTrans;
		movement.InitOrbitAngle(givenVector);
		cactusAnim.Play("AttackAlt", -1, 0f);
	}
	private void Start()
	{
		hitCDStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, hitCount);
		if (!useOrbit)
		{
			moveStopwatchID = ChaosStopwatch.Begin(moveTime);
		}
		else
		{
			cactusAnim.Play("SpawnAlt", -1, 0f);
		}
		SpawnFloorCrack();
	}
	private void FixedUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(hitCDStopwatchID))
		{
		case StopwatchState.Running:
			attackCollider.enabled = true;
			break;
		case StopwatchState.Ready:
			attackCollider.enabled = false;
			break;
		case StopwatchState.Done:
			Reset();
			break;
		}
		if (useOrbit)
		{
			if (orbitTrans != null)
			{
				movement.OrbitTarget(orbitTrans.position, useTransform: true);
			}
		}
		else
		{
			if (moveCompleted)
			{
				return;
			}
			moveLerpValue = ChaosStopwatch.GetTimePercentage(moveStopwatchID) * (float)pongCount;
			moveCompleted = moveLerpValue >= (float)pongCount;
			moveLerpValue = Mathf.PingPong(moveLerpValue, 1f);
			transform.position = Vector2.Lerp(startPosition, endPosition, moveLerpValue);
			if (!audioStopwatch.IsRunning)
			{
				audioStopwatch.IsRunning = true;
				if (isEmpowered)
				{
					string audioID = "Squeak1";
					Vector2? soundOrigin = transform.position;
					float overridePitch = Mathf.Lerp(0.625f, 1.5f, moveLerpValue);
					SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.15f, overridePitch);
				}
				else
				{
					string audioID = "Squeak0";
					Vector2? soundOrigin = transform.position;
					float overridePitch = Mathf.Lerp(0.8f, 1.25f, moveLerpValue);
					SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, 0.15f, overridePitch);
				}
			}
		}
	}
	private void Reset()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			attackCollider.enabled = false;
			thornPartSys.Stop();
			if (useOrbit)
			{
				cactusAnim.Play("DestroyAlt", -1, 0f);
			}
			else
			{
				cactusAnim.Play("Destroy", -1, 0f);
			}
			Object.Destroy(gameObject, 0.5f);
		}
	}
	public void SpawnFloorCrack()
	{
		PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, transform.position, ParticleEffectOverrides.StartLifeTime0p33);
	}
}

public class VinePullDash : BaseDashState
{
	public new static string staticID = "VinePullDash";

	private List<GameObject> targetList = new List<GameObject>();

	private Enemy currentEnemy;

	private Vector2 currentPosition;

	private Transform targetTrans;

	public VinePullDash(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		InitChargeSkillSettings(1, 0f, skillData, this);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		if (!cooldownReady)
		{
			return;
		}
		ApplyStopElement();
		List<GameObject> enemies = GameController.enemies;
		Vector3 position = parent.transform.position;
		float range = 4.25f;
		int layerUpperWallAndObst = ChaosCollisions.layerUpperWallAndObst;
		targetList = Entity.GetAllTargetsInRange(enemies, position, range, playerTagOnly: false, null, null, requireLOS: true, layerUpperWallAndObst);
		SoundManager.PlayWithDistAndSPR("VineSwing", parent.transform.position);
		for (int i = 0; i < 8; i++)
		{
			targetTrans = null;
			currentPosition = Vector3.zero;
			if (i >= targetList.Count || targetList[i] == null || (currentEnemy = targetList[i].GetComponentInParent<Enemy>()) == null || currentEnemy.hurtBoxTransform == null)
			{
				if (i > 4)
				{
					break;
				}
				currentPosition = VinePull.GetRandVineTargetPos(parent.attackOriginTrans.position, inputVector);
			}
			else
			{
				targetTrans = currentEnemy.hurtBoxTransform;
			}
			CreateVine(parent.attackOriginTrans, targetTrans, currentPosition);
		}
		targetList.Clear();
	}

	private void CreateVine(Transform parentTrans, Transform enemyTrans, Vector2 targetPos)
	{
		PoolManager.GetPoolItem<VinePull>("VinePull").Initialize(parentTrans, enemyTrans, targetPos, -inputVector * 0.5f + Globals.GetPerpendicular(inputVector, Globals.RandBool) * UnityEngine.Random.Range(0.125f, 0.2f), inputVector, parent.skillCategory, skillID, currentLevel, IsEmpowered);
	}
}

public class BaseDashState : SkillState
{
	public bool showEffects = true;

	public bool playSFX = true;

	public bool cooldownReady;

	public bool prevCDWasReady;

	public bool finishedDashing;

	public float dashDuration = 0.125f;

	public NumVarStatMod dashDurationMod;

	public BoolVarStat forceEvadeStat;

	public NumVarStatMod evadeMod;

	public BoolVarStatMod airborneMod;

	public BaseDashState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isDash = true;
		isMovementSkill = true;
		forceEvadeStat = new BoolVarStat(newBaseVal: false);
		evadeMod = new NumVarStatMod("DashEvade", 1f, 10, VarStatModType.Override);
		airborneMod = new BoolVarStatMod(SkillState.staticID, newModValue: true);
		dashDurationMod = new NumVarStatMod("dashOverride", dashDuration, 10, VarStatModType.OverrideWithMods);
	}

	public override bool IsReady()
	{
		return parent.MovementEnabled && (!allowSelfTransition || allowRepeating || !repeatLock) && (!isUltimate || IsOverdriveReady());
	}

	public override void OnEnter()
	{
		if (parent.dashSlideIgnored)
		{
			cooldownReady = prevCDWasReady;
			disableStartCooldown = true;
		}
		else
		{
			cooldownReady = cooldownRef.Ready;
			prevCDWasReady = cooldownReady;
			disableStartCooldown = !cooldownReady;
		}
		parent.dashSlideIgnored = false;
		BaseOnEnter();
		if (forceEvadeStat.CurrentValue)
		{
			parent.health.evadeStat.AddMod(evadeMod);
		}
		finishedDashing = false;
		dashDurationMod.modValue = dashDuration;
		parent.movement.dashDurationStat.AddMod(dashDurationMod);
		parent.movement.dashTimer = dashDuration;
		if (parent.inputDevice == null)
		{
			inputVector = Vector2.zero;
		}
		else if (parent.inputDevice.IsMouseDash)
		{
			inputVector = GetInputVector();
		}
		else
		{
			inputVector = GetInputVector(faceInputVector: true, (parent.inputDevice.inputScheme == ChaosInputDevice.InputScheme.Gamepad && ChaosInputDevice.lockControllerAim) ? true : false);
		}
		parent.movement.dashVector = inputVector;
		parent.anim.PlayDirectional(parent.DashAnimStr);
		if (showEffects && !cooldownReady)
		{
			PoolManager.GetPoolItem<DashAirBurst>().Burst(parent.attackOriginTrans.position, inputVector);
			parent.dustEmitter.EmitDirBurst(15, Globals.GetRotationVector(-inputVector).z);
			parent.dashTrails.SetActive(value: true);
		}
		if (playSFX)
		{
			SoundManager.PlayWithDistAndSPR("StandardDash", parent.transform.position);
		}
		parent.TogglePreventFallCollider(status: false);
		parent.ToggleEnemyFloorCollisions(status: false);
		parent.airborneStat.AddMod(airborneMod);
		AnnounceSkillExecuteEvent();
	}

	public override void Update()
	{
		if (finishedDashing)
		{
			ExitTransition();
		}
	}

	public override void FixedUpdate()
	{
		if (!finishedDashing)
		{
			finishedDashing = parent.movement.DashToTarget();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.movement.dashDurationStat.RemoveMod(dashDurationMod.ID);
		DashFinished();
		if (forceEvadeStat.CurrentValue)
		{
			parent.health.evadeStat.RemoveMod(evadeMod);
		}
	}

	public virtual void DashFinished()
	{
		parent.dashTrails.SetActive(value: false);
		parent.TogglePreventFallCollider(status: true);
		parent.airborneStat.RemoveMod(airborneMod);
		parent.ToggleEnemyFloorCollisions();
		parent.movement.EndMovement();
	}

	public virtual void ExitTransition()
	{
		fsm.ChangeState(SlideState.staticID);
	}
}

