using UnityEngine;
public class EarthSeeker : Seeker
{
	public class EarthSeekerIdleState : SeekerIdleState
	{
		private Vector2 currentPosition;
		private bool jumpCompleted;
		private new EarthSeeker parent;
		public EarthSeekerIdleState(string stName, FSM stFSM, EarthSeeker stEnt)
			: base(stName, stFSM, stEnt)
		{
			parent = stEnt;
		}
		public override void Update()
		{
			if (parent.thrownItem.throwComplete)
			{
				if (jumpCompleted)
				{
					CreateBurst(parent.transform.position);
					fsm.ChangeState("Dead");
				}
				else
				{
					base.Update();
				}
			}
		}
		public override void HandleMovement(Transform givenTrans)
		{
			if (!(givenTrans == null))
			{
				if (!jumpCompleted && homing && Vector2.SqrMagnitude(parent.transform.position - givenTrans.position) < parent.jumpRangeSq)
				{
					jumpCompleted = true;
					parent.thrownItem.throwHeight = parent.jumpHeight;
					parent.thrownItem.baseFlightTime = parent.jumpTime;
					parent.thrownItem.ThrowToTargetVector(givenTrans.position);
					SetColliderStatus(givenStatus: false);
					parent.Reset();
				}
				else
				{
					base.HandleMovement(givenTrans);
				}
			}
		}
		private void CreateBurst(Vector2 givenPosition)
		{
			PoolManager.GetPoolItem<FloorCrackEmitter>().Emit(1, givenPosition);
			EarthBurst.CreateBurst(givenPosition, parent.attack.GetAtkInfoAtLevel(2), 2.5f);
			if (parent.isEmpowered)
			{
				PoisonBomb poisonBomb = Globals.ChaosInst<PoisonBomb>(PoisonBomb.Prefab, null, givenPosition);
				poisonBomb.attackBox.SetAttackInfo(parent.attack.atkInfo.skillCategory, "PoisonBurst");
				poisonBomb.targetPosition = givenPosition;
				poisonBomb.baseFlightTime = 0.625f;
				poisonBomb.throwHeight = 3.5f;
				poisonBomb.randomOffset = 0f;
				poisonBomb.attackRadius = 2f;
				poisonBomb.explosionDelay = 0f;
				poisonBomb.useCastingCircle = false;
				poisonBomb.poisonDuration = 1f;
				poisonBomb.poisonType = PoisonType.Green;
			}
		}
	}
	private static GameObject prefab;
	private float jumpRangeSq = 20f;
	private float jumpHeight = 2.25f;
	private float jumpTime = 0.25f;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/EarthSeeker.prefab"));
	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new EarthSeekerIdleState("Idle", fsm, this));
		fsm.AddState(new SeekerFallState("Fall", fsm, this));
		fsm.AddState(new SeekerDeadState("Dead", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}
	public override void Start()
	{
		base.Start();
		if (isEnemy)
		{
			jumpHeight = 2.75f;
			jumpTime = 0.5f;
		}
	}
	public override void OnDead()
	{
		PoolManager.GetPoolItem<RockDebrisEmitter>().EmitSingle(3, transform.position, RockDebrisEmitter.SmallCircleFastExplosionOverride);
		SoundManager.PlayWithDistAndSPR("EarthPebble", transform.position);
		base.OnDead();
	}
	public override void PlaySeekerAudio()
	{
		SoundManager.PlayWithDistAndSPR("EarthPebbleShort", transform.position);
	}
}

using System;
using System.Collections.Generic;
using Chaos.AnimatorExtensions;
