		currentPosition = transform.position;
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		attackBox.gameObject.SetActive(value: false);
		LeafEmitter poolItem = PoolManager.GetPoolItem<LeafEmitter>("FallingLeafEmitter");
		int? particleCount = 4;
		Vector3? position = currentPosition + Vector2.up;
		ParticleSystemOverride radiusTwo = ParticleEffectOverrides.RadiusTwo;
		poolItem.EmitSingle(particleCount, position, radiusTwo);
		PoolManager.GetPoolItem<ParticleEffect>("ThornEmitter").Emit(30, currentPosition);
		PoolManager.GetPoolItem<ParticleEffect>("ThornEmitter").Emit(10, currentPosition, ParticleEffectOverrides.Radius0p25);
		base.ResetProjectile();
		SoundManager.PlayWithDistAndSPR("ExplosionPop", currentPosition);
		if (released)
		{
			if (chargeCompleted)
			{
				CreateCaltropRing();
				EarthBurst.CreateBurst(currentPosition, attackBox.GetAtkInfoAtLevel(3), 2.5f).skipParticleEmit = true;
			}
			else
			{
				EarthBurst.CreateBurst(currentPosition, attackBox.GetAtkInfoAtLevel(2), 2.5f).skipParticleEmit = true;
			}
		}
	}
	public void OnTargetHit(Entity givenEnt)
	{
		if ((hitWall || (!(givenEnt == null) && !(givenEnt is Destructible))) && !targetHit)
		{
			targetHit = true;
			moveSpeed = 3f;
			currentCharge--;
			hitStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, currentCharge);
			flyTime = hitDelay * (float)currentCharge + 1f;
			RefreshFlightTime();
			SoundManager.PlayWithDistAndSPR("PopSnap", transform.position);
		}
	}
	private void CreateCaltropRing()
	{
		caltropInfo = attackBox.GetAtkInfoAtLevel(4);
		AttackInfo.SetFloorTargets(caltropInfo.targetNames);
		currentPosition = transform.position + Vector3.down * 0.9f;
		if (hitWall)
		{
			currentPosition -= releaseVector * 1.5f;
		}
		CreateCaltrop(currentPosition);
		for (int i = 1; i < 12; i += 2)
		{
			CreateCaltrop(currentPosition + Globals.GetRotatedCircleVector(12, i, releaseVector) * 1.5f);
		}
		for (int j = 0; j < 6; j++)
		{
			CreateCaltrop(currentPosition + Globals.GetRotatedCircleVector(6, j, releaseVector) * 2.75f);
		}
	}
	private void CreateCaltrop(Vector2 givenPosition)
	{
		if (Globals.CheckCircle(givenPosition, 0.125f, ChaosCollisions.layerAllWallAndObst))
		{
			currentTC = Globals.ChaosInst<ThrownCaltrop>(ThrownCaltrop.Prefab, null, currentPosition);
			currentTC.attack.SetAttackInfo(caltropInfo);
			currentTC.targetPosition = givenPosition;
			currentTC.lifeTime = 3.5f;
			currentTC.layerMask = ChaosCollisions.layerAllWallAndObst;
			currentTC.useLineCastPosition = true;
		}
	}
	public void EnableColliders(bool status = true)
	{
		for (int i = 0; i < circCols.Length; i++)
		{
			circCols[i].enabled = status;
		}
	}
	public override void OnProjectileCollision(Collider2D other, Projectile otherProjectile, bool doCalculations = true)
	{
		if (doCalculations)
		{
			int num = calculatedDamage - otherProjectile.calculatedDamage;
			otherProjectile.calculatedDamage -= calculatedDamage;
			calculatedDamage = num;
			otherProjectile.OnProjectileCollision(other, this, doCalculations: false);
		}
		if (calculatedDamage > 10)
		{
			currentCharge = Mathf.CeilToInt(calculatedDamage / baseDamage);
			otherProjectile.calculatedDamage = 0;
		}
		else
		{
			currentCharge = 0;
			calculatedDamage = 0;
			HandleCollision(other);
		}
		collidedProjectiles.Add(otherProjectile);
	}
	public override void HandleWallCollision(Collider2D hitCol)
	{
		if (!hitWall)
		{
			hitWall = true;
			updateVelocity = false;
			moveVector = Vector2.zero;
			rigidbody2D.velocity = Vector2.zero;
			attackBox.knockbackMultiplierOverride = -1f;
			attackBox.atkInfo.knockbackMultiplier = -5f;
			attackBox.atkInfo.knockbackOverwrite = false;
			OnTargetHit(null);
			if (Projectile.globalProjectileWallCollisionEvents != null)
			{
				Projectile.globalProjectileWallCollisionEvents(this);
			}
			SoundManager.PlayWithDistAndSPR("PopSnap", transform.position);
		}
	}
}

	public class UseDrillFan : ProjectileAttackState
