		private int atkStopwatchID = -1;

		private bool atkStarted;

		private bool atkEnded;

		private int atkCounter;

		private bool useEmp;

		private EarthDrillProjectile currentDP;

		public override string OnEnterAnimStr => parent.PBAoEAnimStr;

		public UseDrillFan(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			SetAnimTimes(0f, 0.2f, 0.2f, 0.6f, 0.7f);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			useEmp = IsEmpowered;
			atkStarted = false;
			atkEnded = false;
			atkCounter = 0;
		}

		public override void ExecuteSkill()
		{
			if (!atkStarted)
			{
				atkStarted = true;
				atkStopwatchID = ChaosStopwatch.Begin(0.03f, useInterval: true, 0.03f, 3);
				CreateDrillProjectile(parent.attackOriginTrans.position, inputVector);
				CameraController.ShakeCamera(0.1f);
			}
			if (atkEnded)
			{
				base.ExecuteSkill();
			}
		}

		public override void FixedUpdate()
		{
			if (atkStarted && !atkEnded)
			{
				switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
				{
				case StopwatchState.Ready:
					atkCounter++;
					CreateDrillProjectile(parent.attackOriginTrans.position, Globals.GetRotatedCircleVector(atkSpread, atkCounter, inputVector));
					CreateDrillProjectile(parent.attackOriginTrans.position, Globals.GetRotatedCircleVector(atkSpread, -atkCounter, inputVector));
