public class EarthDrillProjectile : Projectile
{
	private static GameObject prefab;
	public bool isEmpowered;
	private float originalSpeed;
	public float speedTime = 0.25f;
	private ChaosQuickStopwatch speedStopwatch = new ChaosQuickStopwatch();
	private bool speedCompleted;
	private float lerpValue;
	private int atkStopwatchID;
	public int atkCount = 5;
	public float atkInterval = 0.125f;
	private bool atkStarted;
	private bool atkCompleted;
	private bool targetHit;
	public Collider2D attackCollider;
	public ParticleSystem partSys;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/EarthDrillProjectile.prefab"));
	public override void Awake()
	{
		base.Awake();
		speedStopwatch.SetDelay(speedTime, stopCurrent: false, autoStart: true);
		Attack attack = attackBox;
		attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
		Attack attack2 = attackBox;
		attack2.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Combine(attack2.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
	}
	public override void Start()
	{
		originalSpeed = moveSpeed;
		moveSpeed = 0f;
		base.Start();
		SoundManager.PlayWithDistAndSPR("EarthDust", transform.position);
		SoundManager.PlayAudioWithDistance("DrillShort", transform.position);
	}
	public override void FixedUpdate()
	{
		if (!speedCompleted)
		{
			lerpValue = speedStopwatch.TimePercentage;
			moveSpeed = Mathf.Lerp(0f, originalSpeed, lerpValue * lerpValue);
			if (lerpValue >= 1f)
			{
				speedCompleted = true;
			}
		}
		if (targetHit)
		{
			if (!atkStarted)
			{
				atkStarted = true;
				atkCompleted = false;
				atkStopwatchID = ChaosStopwatch.Begin(atkInterval, useInterval: true, atkInterval, atkCount);
				flyTime = atkInterval * (float)atkCount * 1.5f;
				RefreshFlightTime(flyTimeOnly: true);
			}
			if (!atkCompleted)
			{
				switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
				{
				case StopwatchState.Running:
					attackCollider.enabled = true;
					break;
				case StopwatchState.Ready:
					attackCollider.enabled = false;
					wallCollider.enabled = true;
					break;
				case StopwatchState.Done:
					atkCompleted = true;
					ResetProjectile();
					break;
				}
			}
		}
		base.FixedUpdate();
	}
	public override bool OnReflect(Vector2 reflectedMoveVector, float damageModifer)
	{
		pointTowardMoveVector = true;
		return base.OnReflect(reflectedMoveVector, damageModifer);
	}
	public override void HandleWallCollision(Collider2D other)
	{
		OnTargetHit(other);
		wallCollider.enabled = false;
		base.HandleWallCollision(other);
		SoundManager.PlayWithDistAndSPR("ImpactEarth", transform.position);
	}
	public override void ResetProjectile()
	{
		if (forcedReturn || !targetHit || atkCompleted)
		{
			Attack attack = attackBox;
			attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(OnTargetHit));
			Vector2 vector = transform.position;
			if (isEmpowered)
			{
				EarthBurst.CreateBurst(vector, attackBox.ChangeAttackInfoLevel(2), 1.5f).attack.knockbackOverwriteVector = moveVector;
				SoundManager.PlayWithDistAndSPR("EarthExplosionShort", vector);
			}
			else
			{
				RockBurstDirectionalEffect poolItem = PoolManager.GetPoolItem<RockBurstDirectionalEffect>("RockBurstDirectionalEffect");
				RockDebrisType debrisType = RockDebrisType.Default;
				int? particleCount = 2;
				Vector3? position = vector;
				Vector3? localEulerAngles = Globals.GetRotationVector(moveVector);
				poolItem.EmitSingle(debrisType, particleCount, position, null, localEulerAngles);
				SoundManager.PlayWithDistAndSPR("EarthDust", vector);
			}
			partSys.Stop();
			partSys.transform.SetParent(null);
			UnityEngine.Object.Destroy(partSys.gameObject, 0.35f);
			base.ResetProjectile();
		}
	}
	private void OnTargetHit(Collider2D col)
	{
		speedStopwatch.Refresh();
		speedCompleted = false;
		targetHit = true;
	}
}
