				jumpTime = Mathf.Lerp(0.1f, 0.25f, jumpLerpVal);
				jumpHeight = Mathf.Lerp(0.375f, 0.75f, jumpLerpVal);
				SetThrowValues();
				parent.throwScript.ThrowToTargetVector(targetPosition);
				SoundManager.PlayAudioWithDistance("StandardJump", startPosition);
				hasLanded = false;
				collidersEnabled = false;
				ToggleObjects(status: false);
