	private int delayStopwatchID = -1;
	private bool spawnCompleted;
	private bool atkCompleted;
	private bool destroyQueued;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/VineJumpWhip.prefab"));
