			{
				attackEndEventHandlers(lastPosition);
			}
		}
	}
	public void SpawnComplete()
	{
		spawnCompleted = true;
		delayStopwatchID = ChaosStopwatch.Begin(0.125f);
	}
	public void EndAttack()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			if (gameObject != null)
			{
				UnityEngine.Object.Destroy(gameObject);
			}
		}
	}
	private void OnDestroy()
	{
		if (this.attack != null)
		{
			Attack attack = this.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		}
	}
	private void OnTargetHit(Entity givenEnt)
	{
		if (!(givenEnt == null) && !(givenEnt is Destructible) && !(givenEnt.transform == null))
		{
			lastPosition = givenEnt.transform.position;
		}
	}
}
